function blogCard([slug,tag,title,image,intro]){return `<article class="blog-card"><a href="/blog/${slug}/">${img(image,title)}<div><span class="product-tag">${tag}</span><h3>${title}</h3><p>${intro}</p><span class="read-link">Read article →</span></div></a></article>`;}
function pageHero(kicker,title,copy){return `<section class="page-hero">${label(kicker)}<h1>${title}</h1><p>${copy}</p><p class="page-update">Updated October 21, 2026</p></section>`;}
page('/','Custom luxury gift box packaging',home);

const catalog=`${pageHero('FULL CATALOG','Custom Gift Box Packaging<br><em>${products.length} Product & Presentation Concepts</em>','Rigid gift boxes, printed shipping cartons, color corrugated mailers, white-card folding cartons, bags and specialty formats. Choose a structure and explore its applications.')}<section class="catalog-section"><div class="catalog-filters" role="group" aria-label="Filter packaging types">${[['all','All products'],['rigid','Rigid boxes'],['mailer','Mailer boxes'],['specialty','Specialty'],['bags','Bags & accessories'],...series.map(g=>[g.id,g.short])].map(([v,t],i)=>`<button data-filter="${v}" aria-pressed="${i===0}" class="${i===0?'active':''}">${t}</button>`).join('')}</div><div class="new-products-note"><h2>Explore our printed packaging series</h2><p>${series.map(g=>`<a href="/product-series/${g.slug}/">${g.name} →</a>`).join(' <span>·</span> ')}</p></div><p class="catalog-count" role="status">${products.length} products</p>${cards()}<div class="catalog-support">${heading('CUSTOM DESIGN & SUPPORT','Need a Different Size, Structure or Finish?','Share your product dimensions and reference direction. The box, insert and brand details can then be reviewed together.',true)}${btn('Discuss Your Packaging Project →')}</div></section><section>${heading('CUSTOM PACKAGING FAQ','Frequently Asked <em>Questions</em>','',true)}${accordion(faqs.slice(0,5))}</section>${cta()}`;
page('/products','Custom gift box product catalog',catalog,'/products/');

function productPage(p){const group=series.find(g=>g.id===p.category);return `<div class="breadcrumb"><a href="/">Home</a><span>›</span><a href="/products/">Products</a><span>›</span><span>${esc(p.name)}</span></div><section class="detail-hero"><div class="detail-grid"><div class="detail-head"><div class="hero-badge">CUSTOM PACKAGING · SPECIFICATION-BASED QUOTES</div><h1>Custom <em>${esc(p.name.replace(/^Custom /,''))}</em></h1></div><figure class="detail-media">${img(p.image,p.name,true,'zoomable')}<figcaption>Original packaging concept · Final specification confirmed per project</figcaption></figure><div class="detail-body"><p class="detail-identity">${esc(p.description)}</p>${group?`<a class="series-parent" href="/product-series/${group.slug}/">${group.name} →</a>`:''}<p>Bring together the right dimensions, paper, insert and brand finish. Share your product measurements, quantity and artwork direction to prepare a project-specific specification.</p><div class="hero-stats"><div><strong>Custom</strong><span>Size & color</span></div><div><strong>Sample</strong><span>Review before approval</span></div><div><strong>By project</strong><span>MOQ & lead time</span></div></div><div class="detail-buttons">${btn('Discuss This Product →',`/quote/?product=${p.id}`)}${btn('Request a Custom Quote','#quote',true)}</div></div></div></section><section class="detail-overview"><div class="two-col"><div>${heading('PRODUCT OVERVIEW',`What Should You Specify for ${esc(p.name)}?`)}<p class="structure-note"><strong>Construction:</strong> ${esc(p.structure)}</p><p>Begin with the product dimensions, weight and arrangement inside the box. Consider how it will be packed, opened and presented, along with any supporting accessories.</p><p>Then review the paper texture, color, artwork coverage, closure and insert. A physical sample gives you a reference for fit, appearance and handling.</p></div>${img(p.image,p.name+' construction and presentation',false,'zoomable')}</div></section><section class="alternate"><div class="narrow-wide">${heading('TECHNICAL SPECIFICATION','Packaging Specification <em>Options</em>','Use these headings to prepare a clear brief. Exact materials and dimensions are confirmed through sampling.')} ${table(['Parameter','Project-specific options'],[['Box structure',esc(p.structure)],['Dimensions','Length × width × height, including inner clearance'],['Material',esc(p.material)],['Print / surface','Printed liner, solid white card or decorative wrap, selected for the structure'],['Color & artwork','Brand color reference and production artwork'],['Finish options',p.finish],['Inner fit',p.insert],['Quantity & timing','Confirmed with your final quotation']])}</div></section><section>${heading('SURFACE FINISHING','Make the Presentation <em>Your Own</em>')}<div class="three-col">${[['Paper & color','Choose a paper feel and coordinated color reference for the exterior and inside.'],['Artwork & finishing','Review foil, embossing, print and ribbon details against the proposed artwork.'],['Insert & accessories','Plan the inner fit, tissue, brand card and other supporting pieces together.']].map(([t,d])=>`<article class="card info-card"><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section class="alternate">${heading('QUOTATION SCOPE','What Changes Your <em>Packaging Quote?</em>','Compare identical dimensions, materials, quantities and finishing requirements.')}<div class="three-col">${[['Structure & dimensions','Board usage, opening style and the fit of the product.'],['Print & finishing','Artwork coverage, paper choice and specialist treatments.'],['Order & delivery','Quantity, sampling scope, packing and destination.']].map(([t,d])=>`<article class="card info-card"><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section>${heading('APPLICATIONS','Customized for Your <em>Product Category</em>')}<div class="application-links">${industryData.filter(([s,n])=>p.application.toLowerCase().includes(n.toLowerCase().split(' ')[0])||['custom-cosmetic-packaging-boxes','subscription-box-packaging','corporate-gifting','electronics-packaging','tea-coffee-packaging','apparel-fashion-packaging','ecommerce-fulfillment'].includes(s)).slice(0,7).map(([s,n])=>`<a href="/industries/${s}/">${n} →</a>`).join('')}</div></section><section class="alternate">${heading('PRODUCTION PROCESS','A Clear Path from Brief to <em>Approval</em>','',true)}${processCards()}</section><section>${heading('PRODUCT FAQ','Frequently Asked <em>Questions</em>','',true)}${accordion(faqs.slice(0,5))}</section><section id="quote" class="quote-section"><div class="quote-inner">${heading('YOUR NEXT STEP','Get a Specification-Based <em>Quote</em>','Share your dimensions, quantity and design direction.',true)}${form()}</div></section><section>${heading('RELATED PRODUCTS','More Packaging <em>Possibilities</em>')} ${cards(products.filter(x=>x.id!==p.id&&x.category===p.category).concat(products.filter(x=>x.id!==p.id)).slice(0,4))}</section>${cta()}`;}
for(const p of products)page('/products/'+p.slug,p.name,productPage(p),'/products/');

const industryCards=list=>`<div class="industry-card-grid">${list.map(([s,n,d,im])=>`<article class="industry-card"><a href="/industries/${s}/">${img(im,n+' gift packaging')}<div><h3>${n} Packaging</h3><p>${d}</p><span>View ${n.toLowerCase()} solutions →</span></div></a></article>`).join('')}</div>`;
for(const g of series){const range=products.filter(p=>p.category===g.id);page('/product-series/'+g.slug,g.name,`${pageHero('PRINTED PACKAGING SERIES',g.name.replace('Color Printed','Color Printed<br><em>')+'</em>',g.intro)}<section class="series-overview"><div class="two-col">${img(g.image,g.name,true,'zoomable')}<div>${label('STRUCTURE & MATERIAL')}<h2>${g.structure}</h2><p>${g.construction}</p><p>${g.material}</p>${btn('Discuss This Series →','/quote/?product='+range[0].id)}</div></div></section><section class="alternate series-range">${heading('APPLICATION-SPECIFIC PRODUCTS','One Series. <em>Six Product Applications.</em>','Explore a concrete starting point, then specify the dimensions, artwork and interior support around your product.')}${cards(range)}</section><section>${heading('BUILD THE RIGHT SPECIFICATION','Printing, Support & <em>Sample Review</em>')}<div class="three-col"><article class="card info-card"><h3>Artwork & printing</h3><p>${g.print}</p></article><article class="card info-card"><h3>What to check</h3><ul>${g.checks.map(t=>`<li>${t}</li>`).join('')}</ul></article><article class="card info-card"><h3>Buyer guide</h3><p>Review construction, material choices and a practical approval checklist.</p><a href="/blog/${g.guide}/">Read the series guide →</a></article></div></section><section class="alternate">${heading('APPLICATION PLANNING','Match the Format to <em>Your Product</em>')}<div class="application-links">${range.map(p=>`<a href="${url(p)}">${p.application} →</a>`).join('')}</div><p class="series-footnote">Each application is an original design concept. Final material, strength, closure, product support and suitability are confirmed through sampling and the project specification.</p></section><section>${heading('FROM BRIEF TO APPROVAL','A Clear Packaging <em>Workflow</em>','',true)}${processCards()}</section><section class="alternate">${heading('RELATED SERIES','Explore More <em>Printed Packaging</em>')}${seriesCards()}</section>${cta()}`,'/products/');}
page('/industries','Packaging solutions by industry',`${pageHero('INDUSTRY SOLUTIONS','Custom Gift Packaging<br><em>Built Around Your Product</em>','Presentation, protection and brand details for different product categories. Explore a direction for your next collection.')}<section>${heading('MATCH THE PACKAGING TO THE PRODUCT','Packaging for Different <em>Buyer Needs</em>')}${industryCards(industryData)}</section><section class="alternate">${heading('FROM PRODUCT TO PRESENTATION','A Considered Packaging <em>Workflow</em>','',true)}${processCards()}</section>${cta()}`,'/industries/');
for(const [slug,name,description,image] of industryData){const relevant=p=>p.image===image||p.application.toLowerCase().includes(name.toLowerCase().split(' ')[0])||(name==='Perfume'&&p.application==='Fragrance')||(['Chocolate','Bakery & food'].includes(name)&&p.application.includes('Confectionery'))||(name==='Wine & spirits'&&p.application.includes('Beverage'));const match=products.filter(relevant);const fresh=products.filter(p=>Number(p.id.slice(1))>60&&relevant(p));page('/industries/'+slug,name+' packaging',`${pageHero('INDUSTRY PACKAGING',`Custom ${name}<br><em>Gift Packaging</em>`,description)}<section class="industry-detail"><div class="two-col">${img(image,name+' packaging concept',true,'zoomable')}<div><h2>Start with the Product.<br><em>Shape the Experience.</em></h2><p>${description} Confirm the product dimensions, interior layout and the way it will be presented or shipped.</p><p>Paper, color, artwork and finishing connect the practical structure to your brand. Review these decisions together with a physical sample.</p>${btn('Get an Industry Quote →','/quote/')}</div></div></section><section class="alternate">${heading('RECOMMENDED DIRECTIONS',`${name} Packaging <em>Options</em>`)}${cards([...new Map([...fresh,...match,...products.slice(0,5)].map(p=>[p.id,p])).values()].slice(0,6))}${seriesCards()}</section><section>${heading('PROJECT PLANNING','From Your Brief to <em>Sample Approval</em>','',true)}${processCards()}</section><section class="alternate">${heading('COMMON QUESTIONS',`${name} Packaging <em>FAQ</em>`,'',true)}${accordion(faqs.slice(0,5))}</section>${cta()}`,'/industries/');}

page('/case-studies','Packaging projects and design concepts',`${pageHero('PACKAGING CASES','Packaging Ideas.<br><em>Real Product Possibilities.</em>','Explore original presentation concepts by product category. Verified company case studies and customer results will be added when supplied.')}<section><div class="case-grid">${[['wellness','Beauty & wellness kit','A coordinated magnetic presentation for a small collection of bottles, jars and accessories.'],['corporate','Corporate presentation set','A tailored insert brings stationery, drinkware and brand details into a complete gift.'],['chocolate','Seasonal confectionery gift','A rigid presentation with separate cavities and a coordinated decorative finish.'],['calendar','Multi-day gift calendar','A numbered sequence of drawers adds a repeated opening experience to a seasonal collection.']].map(([im,t,d])=>`<article class="case-card">${img(im,t)}<div><span class="product-tag">DESIGN CONCEPT</span><h2>${t}</h2><p>${d}</p><dl><div><dt>Structure</dt><dd>Customized around contents</dd></div><div><dt>Branding</dt><dd>Coordinated paper & finishing</dd></div><div><dt>Outcome</dt><dd>Illustrative concept, not a customer claim</dd></div></dl>${btn('Discuss a Similar Project →')}</div></article>`).join('')}</div></section>${cta()}`,'/case-studies/');

page('/certifications','Certificates and quality documentation',`${pageHero('CERTIFICATIONS & COMPLIANCE','Clear Documentation.<br><em>Verified Project Information.</em>','This section is reserved for the company certificates, material records and testing documents applicable to your business and orders.')}<section><div class="document-grid">${[['FSC','Paper sourcing records'],['ISO 9001','Quality management records'],['SGS / TEST','Relevant testing documents'],['AUDIT','Facility and audit records']].map(([n,t])=>`<article class="card document-card"><span class="document-code">${n}</span><h2>${t}</h2><p>Document number, holder, validity dates and applicable scope will be added after verification.</p><span class="pending-label">Document awaiting company information</span></article>`).join('')}</div></section><section class="alternate"><div class="narrow-wide">${heading('DOCUMENT REVIEW','What to Check in a <em>Certificate</em>')}${table(['Review point','Information to confirm'],[['Document holder','Registered company name and address'],['Scope','Material, activity or facility covered'],['Validity','Current issue and expiry dates'],['Project relevance','Whether the exact material or order is included']])}</div></section>${cta()}`,'/certifications/');

page('/about','About our custom packaging business',`${pageHero('ABOUT OUR COMPANY','Custom Gift Packaging.<br><em>Your Brand in Every Detail.</em>','A packaging project brings together product fit, materials, print, finishing and production planning. This website introduces the structures and details available to explore.')}<section><div class="two-col">${img('hero','Original FORME gift packaging concepts',true)}<div>${label('COMPANY PROFILE')}<h2>A Packaging Partner<br><em>for Your Next Project.</em></h2><p>Company history, location, team and verified production information will be added here using your own business details.</p><p>Explore the complete product range, compare structures and prepare a brief with your product dimensions, quantity and brand direction.</p>${btn('Browse Our Product Range →','/products/')}</div></div></section><section class="alternate" id="factory">${heading('PRODUCTION & SAMPLING','From an Initial Idea to a <em>Confirmed Specification</em>','Review the structure, material, artwork and physical sample before approving a production plan.')}<div class="two-col"><video class="feature-video" controls playsinline preload="none" poster="/assets/showcase.webp"><source src="/assets/forme-film.mp4" type="video/mp4"></video><div><h3>A closer look at the collection</h3><p>This original film presents generated packaging concepts. Your company facility images, equipment information and production footage can be added in this section when available.</p><a href="/factory-tour/">View the production overview →</a></div></div></section><section>${heading('A CLEAR PROJECT PROCESS','Four Steps to Your <em>Packaging Collection</em>','',true)}${processCards()}</section>${cta()}`,'/about/');
page('/factory-tour','Production and packaging overview',`${pageHero('PRODUCTION OVERVIEW','From Structure to Finish.<br><em>A Closer Look.</em>','The sample and specification connect your product requirements with the planned material, print, insert and finishing details.')}<section><video class="tour-video" controls playsinline preload="none" poster="/assets/showcase.webp"><source src="/assets/forme-film.mp4" type="video/mp4"><track kind="captions" src="/assets/film.vtt" srclang="en" label="English" default></video><p class="media-note">Original concept film. Company facility photographs and production footage will be added when supplied.</p></section><section class="alternate">${heading('PROJECT CHECKPOINTS','The Details to Confirm <em>Before Production</em>')}${processCards()}</section>${cta()}`);

function estimator(){return `<aside class="estimator" id="estimator"><h2>Reference Planning Estimator</h2><p>An illustrative comparison, not a live supplier quotation.</p><label for="estType">Box type</label><select id="estType">${[['magnetic','Magnetic Rigid Box'],['mailer','Custom Mailer Box'],['drawer','Sliding Drawer Box'],['tube','Cylinder Tube Box'],['foldable','Foldable Magnetic Box'],['bag','Luxury Paper Bag'],['rigid','Lid & Base Box'],['corrugated-cartons','Printed Shipping Carton'],['corrugated-boxes','Printed Corrugated Mailer'],['white-card','Printed White Card Carton']].map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><label for="estQty">Quantity</label><select id="estQty">${[500,1000,2000,5000,10000].map(n=>`<option value="${n}">${n.toLocaleString()} pcs</option>`).join('')}</select><label for="estFinish">Finishing</label><select id="estFinish">${[['standard','Matte lamination'],['soft','Soft touch'],['foil','Foil stamping'],['emboss','Embossing'],['combined','Foil + soft touch + spot UV']].map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><div class="estimate-result" aria-live="polite"><span>ILLUSTRATIVE UNIT FIGURE</span><strong id="estimate-unit">$3.20</strong><p>Estimated product subtotal <b id="estimate-total">$1,600.00</b></p></div><p class="estimate-disclaimer">Example planning values only. Box dimensions, materials, sampling, shipping, taxes and actual order terms require a separate confirmed quote.</p><button class="btn-primary" type="button" id="use-estimate">Use These Project Details →</button><p class="estimate-status" role="status"></p><div class="contact-sidebar"><h3>Contact information</h3><p>Email: ${esc(site.email||'to be added')}</p><p>Phone / WhatsApp: ${esc(site.phone||'to be added')}</p><p>Address: ${esc(site.address||'to be added')}</p></div></aside>`;}
page('/quote','Request a custom packaging quote',`${pageHero('CUSTOM QUOTE · NO COMMITMENT','Get Your Custom Quote.<br><em>Start with the Details.</em>','Share your product, preferred packaging, quantity and design direction. The final price, minimum quantity and schedule are confirmed for your project.')}<section class="quote-page-layout">${estimator()}<div class="quote-page-form">${form(true)}</div></section><section class="alternate">${heading('OUR PACKAGING RANGE','What Can We Make <em>for Your Product?</em>')}${cards(products.slice(4,8))}</section><section>${heading('BEFORE THE BULK ORDER','How a Physical Sample <em>Helps Your Project</em>','',true)}${processCards()}</section><section class="alternate">${heading('QUICK ANSWERS','Frequently Asked <em>Questions</em>','',true)}${accordion(faqs.slice(0,5))}</section>`);

page('/blog','Packaging blog and buyer guides',`${pageHero('PACKAGING INSIGHTS','Ideas, Materials &<br><em>Practical Buyer Guides.</em>','Explore structures, finishing details, sampling questions and the information that makes a packaging brief clearer.')}<section><div class="blog-card-grid">${guideData.map(blogCard).join('')}</div></section>${cta()}`,'/blog/');
for(const article of articles){const {slug,tag,title,image,intro,sections,sources=[]}=article;const words=(intro+sections.map(x=>x[2].replace(/<[^>]*>/g,' ')).join(' ')).split(/\s+/).length;page('/blog/'+slug,title,`<div class="breadcrumb"><a href="/">Home</a><span>›</span><a href="/blog/">Blog</a><span>›</span><span>${esc(tag)}</span></div><article class="guide-article"><header>${label(tag)}<h1>${title}</h1><div class="article-meta"><span>FORME Packaging editorial</span><span>Updated October 21, 2026</span><span>${Math.max(3,Math.ceil(words/180))} min read</span></div><div class="article-lead"><p>${intro}</p><figure>${img(image,title,true)}<figcaption>Original packaging concept · Construction and details vary by specification</figcaption></figure></div></header><div class="guide-body"><aside class="contents"><strong>In this guide</strong>${sections.map(([id,t])=>`<a href="#${id}">${t}</a>`).join('')}<a class="contents-quote" href="/quote/">Discuss your packaging →</a></aside><div class="article-prose">${sections.map(([id,t,html])=>`<section id="${id}"><h2>${t}</h2>${html}</section>`).join('')}${sources.length?`<aside class="article-sources"><h3>Further reading</h3>${sources.map(k=>`<a href="${researchSources[k][1]}" target="_blank" rel="noopener noreferrer">${researchSources[k][0]} ↗</a>`).join('')}</aside>`:''}<div class="article-next"><h3>Turn the guide into a clear packaging brief.</h3><p>Share product measurements, quantity, artwork direction and delivery needs.</p>${btn('Prepare Your Packaging Brief →')}</div></div></div></article><section class="alternate">${heading('KEEP EXPLORING','Related Packaging <em>Guides</em>')}<div class="blog-card-grid">${guideData.filter(a=>a[0]!==slug).slice(slug.includes('corrugated')||slug.includes('white-card')?-3:0,slug.includes('corrugated')||slug.includes('white-card')?undefined:3).slice(0,3).map(blogCard).join('')}</div></section>`,'/blog/');}


const referencePages=[['gift-box-types','Gift box types compared','Compare different opening formats and choose a structure around your product.'],['gift-box-materials-guide','Gift box materials guide','Paper, board, inserts and finishing choices for a considered specification.'],['gift-box-size-guide','Gift box size guide','Start with the packed product and confirm internal clearance with a sample.'],['rigid-gift-boxes','Custom rigid gift boxes','Explore magnetic, drawer, lift-off lid and specialty rigid presentation formats.'],['custom-gift-boxes-with-logo','Custom gift boxes with your logo','Bring printed artwork, foil, embossing and coordinated colors together.'],['guides/moq-guide','Custom packaging order quantities','Review the quantity for each custom size, artwork and finishing combination.'],['guides/price-guide','Custom packaging planning guide','Compare structures and the choices that contribute to a project quotation.']];
for(const [slug,title,intro] of referencePages)page('/'+slug,title,`${pageHero('PACKAGING BUYER RESOURCES',title,intro)}<section><div class="narrow-wide">${heading('START WITH THE SPECIFICATION','Compare Your <em>Packaging Options</em>')}${table(['Format','Opening style','Typical planning considerations'],[['Magnetic rigid box','Book-style hinged lid','Hinge, closure, inner fit and wrapped surfaces'],['Lid & base','Separate lift-off lid','Lid depth, fit, insert and finishing'],['Drawer box','Sliding tray and sleeve','Clearance, pull tab and lining'],['Mailer','Folded tuck-front carton','Packing, transit, print and protective insert'],['Paper tube','Cylinder and fitted lid','Diameter, height, wrapping and product support'],['Printed shipping carton','Four-flap corrugated case','Packed weight, board strength, dividers and tape closure'],['Printed corrugated box','Die-cut hinged mailer','Folded sidewalls, locking tabs and interior print'],['White-card carton','Folded tuck closure','Solid paperboard caliper, crease, glued seam and bottom']])}<p class="table-note">Final dimensions, material grades, order requirements and prices are confirmed for each project.</p></div></section><section class="alternate">${heading('PRODUCT EXAMPLES','Explore Related <em>Structures</em>')}${cards([...products.slice(4,10),products[60],products[66],products[72]])}${seriesCards()}</section><section>${heading('PROJECT FAQ','Questions Before You <em>Begin</em>','',true)}${accordion(faqs.slice(0,5))}</section>${cta()}`);

page('/privacy','Privacy notice',`${pageHero('PRIVACY & YOUR INFORMATION','Your Project Details.<br><em>Your Choice.</em>','How this packaging website preview handles project briefs and saved drafts.')}<section><div class="legal-copy"><h2>Project inquiry information</h2><p>The preview prepares a downloadable project brief in your browser. It does not send your name, contact details, message or selected file to a supplier or external form service.</p><h2>Saved drafts</h2><p>A draft is stored locally only when you choose Save draft. You can remove it using Clear saved draft on the form. The selected file itself is never stored in the draft.</p><h2>Reference attachments</h2><p>A chosen file remains on your device. The downloadable brief records its filename so you can share the file separately with the intended packaging contact.</p><h2>Email and contact actions</h2><p>When an actual email address is configured, an email action opens a draft in your email application for you to review and send. Company contact details are currently placeholders.</p><h2>Cookies and analytics</h2><p>The website uses no advertising or analytics trackers. Locally hosted product images, videos and fonts are supplied with the website.</p></div></section>`);
page('/support','Packaging project support',`${pageHero('PROJECT SUPPORT','A Clear Brief.<br><em>A Better Starting Point.</em>','Find answers about product requirements, samples, files and the information needed to plan your packaging.')}<section>${accordion()}</section>${cta()}`);

// Preserve previously shared local links while routing them to the rebuilt site.
const oldRoutes={'collections.html':'/products/','bespoke.html':'/#finishing','about.html':'/about/','journal.html':'/blog/','contact.html':'/quote/','product-magnetic.html':url(products[4]),'product-rigid.html':url(products[9]),'product-drawer.html':url(products[6]),'product-tube.html':url(products[7]),'product-mailer.html':url(products[5]),'product-bag.html':url(products[8]),'guide-choose-your-box.html':'/gift-box-types/','guide-finishing-details.html':'/#finishing','guide-thoughtful-materials.html':'/gift-box-materials-guide/'};
for(const [file,href] of Object.entries(oldRoutes))writeHTML('dist/'+file,`<!doctype html><html lang="en"><meta charset="UTF-8"><meta http-equiv="refresh" content="0;url=${href}"><meta name="robots" content="noindex,follow"><link rel="canonical" href="${site.origin}${href.split('#')[0]||'/'}"><title>Continue to ${site.company}</title><a href="${href}">Continue to the updated page</a></html>`);
writeFileSync('dist/sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${pageRoutes.map(r=>`<url><loc>${site.origin}${r==='/'?'/':r+'/'}</loc></url>`).join('')}</urlset>`);
writeFileSync('dist/robots.txt',`User-agent: *\nAllow: /\nSitemap: ${site.origin}/sitemap.xml\n`);
console.log(`Built ${pageRoutes.length} complete pages, ${products.length} product detail routes and all reference navigation destinations.`);
